package dev.pocketengine.runtime.usage;
import java.nio.file.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class TaskDetailedTraceTest {
 private static final String TASK="10000000-0000-0000-0000-000000000001",RUN="20000000-0000-0000-0000-000000000002";
 @Test public void offOnInvalidatesOldTicketAndLateRunCannotCollectAgain()throws Exception{Path dir=Files.createTempDirectory("pw-trace-generation");TaskDetailedTrace store=new TaskDetailedTrace(dir,true);assertEquals(-1,store.ticket());assertNull(store.start(-1,TASK,RUN,1));store.configure(true,1);long ticket=store.ticket();var session=store.start(ticket,TASK,RUN,1);assertNotNull(session);store.configure(false,1);store.configure(true,1);assertNull(store.start(ticket,TASK,RUN,1));session.events(event->{}).emit(new JSONObject().put("type","tool").put("tool","phone_observe").put("status","completed").put("message","MUST-NOT-PERSIST"));JSONObject archive=store.read(RUN);assertTrue(archive.getBoolean("available"));assertEquals(1,archive.getJSONArray("spans").length());assertFalse(archive.toString().contains("MUST-NOT-PERSIST"));}
 @Test public void originalReceiptsAndToolEventsRetainMetadataOnlyWithinTheBound()throws Exception{Path dir=Files.createTempDirectory("pw-trace-native");TaskDetailedTrace store=new TaskDetailedTrace(dir,true);TaskDetailedTrace.install(store);try{store.configure(true,1);var session=store.start(store.ticket(),TASK,RUN,1);var sink=session.events(event->{});for(int i=0;i<1050;i++)sink.emit(new JSONObject().put("type","tool").put("tool","phone_query").put("status","completed").put("message","PROMPT-MUST-NOT-PERSIST").put("receipt",new JSONObject().put("apiKey","KEY-MUST-NOT-PERSIST")));
  InferenceReceipt receipt=new InferenceReceipt("30000000-0000-0000-0000-000000000003",new InferenceReceipt.Context(TASK,RUN,1,InferenceReceipt.Purpose.MAIN,""),InferenceReceipt.Outcome.COMPLETED,System.currentTimeMillis(),System.currentTimeMillis(),1000,new JSONObject(),new JSONObject());TaskDetailedTrace.receiptCommitted(receipt);session.close();JSONObject archive=store.read(RUN);assertTrue(archive.getBoolean("truncated"));assertTrue(archive.getJSONArray("spans").length()<=1025);assertFalse(archive.toString().contains("MUST-NOT-PERSIST"));assertTrue(store.snapshot().getLong("retainedBytes")<=1048576);assertFalse(store.snapshot().getBoolean("automaticUpload"));}finally{TaskDetailedTrace.install(null);}}
}
